const express = require('express');
const { Duplex } = require('stream');
const fs = require('fs');
const path = require('path');
const { CallLog } = require('../models/callLog');

const app = express();

class AudioDuplexPipeline extends Duplex {
  constructor(sourceFile) {
    super();
    this.source = fs.createReadStream(sourceFile);
    this.source.on('data', (chunk) => this.push(chunk));
    this.source.on('end', () => this.push(null));
    this.source.on('error', (err) => this.destroy(err));
  }

  _read(size) {}
  _write(chunk, encoding, callback) {
    callback();
  }
}

app.get('/api/calls/:recordingId/audio-stream', async (req, res) => {
  if (!req.session || !req.session.userId) {
    return res.status(401).send('Authentication required');
  }

  // Validate that the call recording belongs to the requesting customer or organization
  const callRecord = await CallLog.findOne({
    recordingId: req.params.recordingId,
    customerId: req.session.userId
  });

  if (!callRecord) {
    return res.status(403).send('Access denied or recording does not exist');
  }

  const recordingPath = path.join('/var/telephony/recordings', `${req.params.recordingId}.wav`);
  if (!fs.existsSync(recordingPath)) {
    return res.status(404).send('Recording file missing');
  }

  res.setHeader('Content-Type', 'audio/wav');
  const duplexStream = new AudioDuplexPipeline(recordingPath);

  duplexStream.pipe(res);
});

app.listen(3002);
